@Test
public void testWithShardRouterGetShardRight() {
    String clusterName = "default";
    String database = "test_db";
    String localTable = "test_table_local";
    String localTableEngine = "ReplicatedMergeTree";
    String localTableDDL = "create table test_db.test_table_local (token String) ENGINE = ReplicatedMergeTree()";
    String username = "test";
    String password = "123456";
    // Assuming there are 28 clickhouse nodes with 2 replica
    List<Shard> shardList = new ArrayList<>();
    Set<Integer> expected = new TreeSet<>();
    for (int i = 1; i <= 14; i++) {
        expected.add(i);
        Shard shard = new Shard(i, 1, 1, "shard" + i, "shard" + i, 9000, database, username, password, Collections.emptyMap());
        shardList.add(shard);
    }
    DistributedEngine distributedEngine = new DistributedEngine(clusterName, database, localTable, localTableEngine, localTableDDL);
    ClickhouseProxy proxy = Mockito.mock(ClickhouseProxy.class);
    Mockito.when(proxy.getClickhouseConnection(Mockito.any(Shard.class))).thenReturn(null);
    Mockito.when(proxy.getClickhouseDistributedTable(Mockito.eq(null), Mockito.anyString(), Mockito.anyString())).thenReturn(distributedEngine);
    Mockito.when(proxy.getClusterShardList(Mockito.eq(null), Mockito.eq("default"), Mockito.eq("test_db"), Mockito.eq(9000), Mockito.eq(null), Mockito.eq(null), Mockito.eq(Collections.emptyMap()))).thenReturn(shardList);
    String shardKey = "token";
    String shardKeyType = "String";
    ShardMetadata shardMetadata = new ShardMetadata(shardKey, shardKeyType, shardKey, database, localTable, localTableEngine, true, shardList.get(0));
    Set<Integer> actual = new TreeSet<>();
    ShardRouter shardRouter = new ShardRouter(proxy, shardMetadata);
    for (int i = 0; i < 10000000; i++) {
        byte[] randomBytes = new byte[16];
        ThreadLocalRandom.current().nextBytes(randomBytes);
        Shard shard = shardRouter.getShard(Arrays.toString(randomBytes));
        int shardNum = shard.getShardNum();
        actual.add(shardNum);
    }
    Assertions.assertEquals(expected, actual);
}

