    MockedStatic<RestService> restServiceMockedStatic = Mockito.mockStatic(RestService.class);
    restServiceMockedStatic.when(() -> RestService.findPartitions(any(), any(), any())).thenReturn(buildPartitionDefinitions(partitionNums));
    Set<DorisSourceSplit> splitSet = new HashSet<>();
    for (int i = 0; i < parallelism; i++) {
        ParallelSource parallelSource = new ParallelSource(dorisSource, null, parallelism, "parallel-doris-source" + i, i);
